-- SahiMilo service catalog imported from the supplied workbook.
-- Run in Supabase Dashboard > SQL Editor. Safe to run again.
begin;

create table if not exists public.service_catalog (
  id bigint generated by default as identity primary key,
  category text not null,
  service text not null,
  description text not null default '',
  sort_order integer not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint service_catalog_category_service_key unique (category, service)
);

alter table public.service_catalog enable row level security;
drop policy if exists "anyone reads active service catalog" on public.service_catalog;
create policy "anyone reads active service catalog"
on public.service_catalog for select
to anon, authenticated
using (active = true);

grant select on public.service_catalog to anon, authenticated;
revoke insert, update, delete on public.service_catalog from anon, authenticated;

on conflict (category, service) do update set
  description = excluded.description,
  sort_order = excluded.sort_order,
  active = excluded.active,
  updated_at = now();

commit;
notify pgrst, 'reload schema';

select count(*) as active_services,
       count(distinct category) as categories
from public.service_catalog
where active = true;
